  if (word.isEmpty) return [];
  Map<String, Set<String>> wordNeighbors = {};
  for (String w in dictionary) {
    if (w.length != word.length) continue;
    bool isPrefix = false;
    for (int i = 0; i < w.length; i++) {
      if (w.substring(i, i + 1) != word.substring(i, i + 1)) {
        isPrefix = true;
        break;
      }
    }
    if (isPrefix) continue;
    for (int j = 0; j < w.length; j++) {
      if (w.substring(j, j + 1) != word.substring(j, j + 1)) {
        String suffix = word.substring(j + 1);
        if (!wordNeighbors.containsKey(suffix)) {
          wordNeighbors[suffix] = {};
        }
        wordNeighbors[suffix]!.add(w);
      }
    }
  }
  List<String> result = [];
  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordNeighbors.containsKey(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (dp[word.length]) result.add(word);

  for (int i = word.length - 1; i >= 0; i--) {
    if (dp[i] && wordNeighbors.containsKey(word.substring(i, word.length))) {
      List<String> neighborWords = wordNeighbors[word.substring(i, word.length)]!.toList();
      for (String n in neighborWords) {
        result.add(n);
      }
    }
  }
  return result;
}

