int minWordBreak(String s, List<String> wordDictionary) {
  Map<String, int> memo = {};
  int count = 0;

  bool wordBreak(String word, List<String> dict) {
    if (word.isEmpty) return true;
    if (dict.isEmpty) return false;

    if (memo.containsKey(word)) return memo[word]!;
    bool found = false;

    for (String word2 in dict) {
      if (word2 == word) continue;
      if (word2.length > word.length) continue;

      if (wordBreak(word.substring(0, word2.length), dict)) {
        memo[word] = count + 1;
        found = true;
        break;
      }
    }

    memo[word] = found ? count + 1 : 0;
    return found;
  }

  wordBreak(s, wordDictionary);
  return memo.containsKey(s) ? memo[s]! : -1;
