List<String> wordBreakHelper(String s, List<String> wordDictionary) {
  if (s.isEmpty) return [];
  if (wordDictionary.isEmpty) return [];

  List<List<bool>> dp = List.generate(s.length + 1, (_) => List.filled(s.length + 1, false));
  dp[0][0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j][0]) {
        dp[i][0] = true;
      }

      for (int k = j + 1; k < i; k++) {
        if (dp[j][k] && wordDictionary.contains(s.substring(j, k))) {
          dp[i][k] = true;
          break;
        }
      }
    }
  }

  List<String> result = [];
  String current = '';
  int end = s.length;

  void backtrack(int start) {
    if (start == end) {
      result.add(current);
      return;
    }

    for (int k = start; k < end; k++) {
      if (dp[start][k] && wordDictionary.contains(s.substring(start, k))) {
        current += s.substring(start, k);
        backtrack(k + 1);
        current = current.isEmpty ? '' : current;
      }
    }
  }

  backtrack(0);
  return result;
}

