          (top['data'] as List<String>).add(entry);
        }
      }
    }
  }

  while (stack.isNotEmpty) {
    final top = stack.removeLast();
    if (top['type'] == 'BEGIN') {
      history.add((top['data'] as List<String>));
    } else if (top['type'] == 'ADD') {
      result.add((top['data'] as List<String>).join('+'));
    }
  }

  result.sort();
  return result;
}

