void fn0() {

  String text = "HERE IS A SIMPLE EXAMPLE";
  String pattern = "EXAMPLE";

  int m = text.length;
  int n = pattern.length;

  List<List<int>> dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  for (int i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (int j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (text[i - 1] == pattern[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        int insertOp = dp[i][j - 1] + 1;
        int deleteOp = dp[i - 1][j] + 1;
        dp[i][j] = insertOp < deleteOp ? insertOp : deleteOp;
      }
    }
  }

  int k = dp[m][n];
  if (k == 0) {
    print("Pattern not found.");
  } else {
    List<int> positions = [];
    int i = m;
    int j = n;
    while (i > 0 && j > 0) {
      if (text[i - 1] == pattern[j - 1]) {
        positions.add(i - 1);
        i--;
        j--;
      } else if (dp[i - 1][j] < dp[i][j - 1]) {
        i--;
      } else {
        j--;
      }
    }
    print("Pattern found at positions: $positions");
  }
}

