    int m = pattern.length;

    for (int i = 0; i <= n - m; i++) {
      bool match = true;
      for (int j = 0; j < m; j++) {
        if (text[i + j] != pattern[j]) {
          match = false;
          break;
        }
      }
      if (match) return true;
    }
    return false;
  }

  bool kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    if (m > n) return false;

    List<int> lps = List<int>.filled(m, 0);

    int i = 0;
    int j = 1;

    while (i < n) {
      if (pattern[j] == text[i]) {
        i++;
        j++;
      }
      if (j == m) {
        return true;
      }
      if (i < n && pattern[j] != text[i]) {
        if (j != 0) j = lps[j - 1];
        else i++;
      }
    }
    return false;
  }

  if (linearSearch(text, pattern)) {
    print("Pattern found at positions: ${List.generate(linearSearch(text, pattern).length, (i) => i + 1)}");
  } else {
    print("Pattern not found.");
  }

  if (kmpSearch(text, pattern)) {
    print("Pattern found at positions: ${List.generate(kmpSearch(text, pattern).length, (i) => i + 1)}");
  } else {
    print("Pattern not found.");
  }
}

