class User {
  final String name;
  final Map<String, dynamic> permissions;

  User(this.name, [this.permissions = const {'read': false, 'write': false, 'admin': false}]);

  String getRole() {
    if ('admin' in permissions && permissions['admin']!) {
      return 'admin';
    }
    if ('editor' in permissions && permissions['editor']!) {
      return 'editor';
    }
    if ('viewer' in permissions && permissions['viewer']!) {
      return 'viewer';
    }
    return 'user';
  }

  bool can(String action) {
    return permissions.containsKey(action) && permissions[action]!;
  }
}

