int fn0(List<int> startTimes, List<int> endTimes, int k, int minGap) {
  if (k <= 0 || startTimes.length != endTimes.length) return -1;
  int n = startTimes.length;
  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + startTimes[i] - endTimes[i] - minGap;
  }
  int low = 0, high = n;
  while (low < high) {
    int mid = (low + high) >> 1;
    if (prefix[mid + 1] >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

