int fn0(List<int> sortedPrices, List<int> targets, int minLen, int maxLen) {
  int left = 0, right = sortedPrices.length - 1, ans = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedPrices[mid] <= targets[0]) left = mid + 1;
    else right = mid - 1;
  }
  left = left < sortedPrices.length - 1 ? left : sortedPrices.length - 1;
  right = left + minLen - 1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedPrices[mid] <= targets[0]) left = mid + 1;
    else right = mid - 1;
  }
  if (left > right) {
    left = left - minLen + 1;
    right = left + maxLen - 1;
  }
  if (left > right) return ans;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedPrices[mid] <= targets[0]) left = mid + 1;
    else right = mid - 1;
  }
  if (left > right) {
    left = left - minLen + 1;
    right = left + maxLen - 1;
  }
  int bestStart = left > right ? left : right;
  int bestEnd = left > right ? right : left;
  return bestStart < bestEnd ? bestStart : bestEnd;
}

