int fn0(List<int> parent, List<int> rank, int leader, int k) {
  int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  int union(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return false;
    if (rank[a] < rank[b]) { parent[a] = b; }
    else if (rank[a] > rank[b]) { parent[b] = a; }
    else { parent[b] = a; rank[a]++; }
    return true;
  }

  int size(int x) {
    while (parent[x] != x) {
      x = parent[x];
    }
    return x;
  }

  for (int i = 0; i < parent.length; i++) {
    parent[i] = i; rank[i] = 0;
  }

  for (int i = 0; i < parent.length; i++) {
    if (parent[i] == leader) {
      if (size(i) < k) return -1;
    } else {
      union(i, leader);
    }
  }
  return leader;
}

