int fn0(List<int> signalBins, List<int> counts, int windowSize, int k) {
  if (k <= 0 || windowSize <= 0) return -1;
  int n = signalBins.length;
  if (n < windowSize) return -1;
  int prefix = 0;
  for (int i = 0; i < windowSize; i++) {
    prefix += signalBins[i];
  }
  int left = prefix;
  int right = n - windowSize;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    int prefixMid = 0;
    for (int i = 0; i < windowSize; i++) {
      prefixMid += signalBins[i + mid];
    }
    if (prefixMid >= k) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  int result = left;
  if (result >= 0) {
    int prefixResult = 0;
    for (int i = 0; i < windowSize; i++) {
      prefixResult += signalBins[i + result];
    }
    if (prefixResult >= k) {
      result = left;
    } else {
      for (int start = 0; start < n - windowSize + 1; start++) {
        int prefixStart = 0;
        for (int i = 0; i < windowSize; i++) {
          prefixStart += signalBins[i + start];
        }
        if (prefixStart >= k) {
          result = start;
          break;
        }
      }
    }
  }
  if (result >= 0) {
    int countPrefix = 0;
    for (int i = 0; i < windowSize; i++) {
      countPrefix += counts[i + result];
    }
    if (countPrefix >= k) {
      return result;
    } else {
      return -1;
    }
  } else {
    return -1;
  }
}

