List<int> fn0(List<String> logLines) {
  Set<String> seen = {};
  Set<String> duplicates = {};
  List<int> result = [];

  for (String line in logLines) {
    if (line.isEmpty) continue;
    int hash = 0;
    for (int i = 0; i < line.length; i++) {
      hash += line.codeUnitAt(i);
    }
    String fingerprint = line + '#' + hash.toString();
    if (!seen.add(fingerprint)) {
      duplicates.add(fingerprint);
    }
  }

  if (duplicates.isEmpty) {
    result.add(-1);
  } else {
    List<String> parts = duplicates.toList();
    parts.sort((a, b) {
      int cmp = (a.split('#').length - 1).compareTo((b.split('#').length - 1));
      if (cmp != 0) return cmp;
      int aHash = int.parse(a.split('#').last);
      int bHash = int.parse(b.split('#').last);
      return aHash.compareTo(bHash);
    });

    List<int> indices = [];
    for (int i = 0; i < parts.length; i++) {
      indices.add(i);
    }

    for (int i = 0; i < indices.length - 1; i++) {
      int j = indices[i + 1];
      int index1 = indices[i];
      int index2 = indices[j];

      int hash1 = int.parse(parts[index1].split('#').last);
      int hash2 = int.parse(parts[index2].split('#').last);
      int cmp = hash2.compareTo(hash1);
      if (cmp != 0) return cmp;

      int lineCmp = parts[index1].split(' ').length.compareTo(parts[index2].split(' ').length);
      if (lineCmp != 0) return lineCmp;

      indices[i] = index2;
      indices[j] = index1;
    }

    result = indices;
  }

  return result;
}

