    for (final entry in log) {
      final parts = entry.split(' ');
      if (parts.length != 4) continue;
      final int? floor = int.tryParse(parts[2]);
      final int? time = int.tryParse(parts[3]);
      if (floor == null || time == null) continue;
      final String key = '$floor:$time';
      if (!seen.contains(key)) continue;
      if (floor == f.codeUnitAt(0)) {
