List<int> fn0(List<String> events) {
  Set<int> openSeats = {};
  Set<String> occupied = {};
  List<int> history = [];
  bool rootOccupied = false;

  for (String event in events) {
    if (event == '[Occupied]') {
      rootOccupied = true;
    } else if (event == ']') {
      rootOccupied = false;
    } else if (event == '!') {
      if (history.isNotEmpty) {
        openSeats = history.removeLast();
      }
    } else {
      String action = event[0];
      int row = event.codeUnitAt(1) - 65 + 1;
      int col = int.parse(event.substring(2));
      int seat = row * 100 + col;

      if (action == '(') {
        openSeats.add(seat);
        history.add(openSeats);
      } else if (action == ')') {
        if (rootOccupied) break;
        openSeats.remove(seat);
        history.add(openSeats);
      } else if (action == '^') {
        if (rootOccupied) break;
        Set<int> otherOpen = {};
        for (int s in openSeats) {
          if (s != seat) otherOpen.add(s);
        }
        openSeats = otherOpen;
        history.add(openSeats);
      } else if (action == '-') {
        if (rootOccupied) break;
        List<int> next = <int>[];
        for (int s in openSeats) {
          if (s != seat) next.add(s);
        }
        openSeats = next;
        history.add(openSeats);
      } else if (action == '<') {
        if (rootOccupied) break;
        Set<String> conflicts = <String>{};
        for (int s in openSeats) {
          int row = s ~/ 100;
          int col = s % 100;
          conflicts.add('${row + 1}${col + 1}');
        }
        openSeats = conflicts.toSet();
        history.add(openSeats);
      } else if (action == '[') {
        occupied.add('${row + 1}${col + 1}');
      } else if (action == ']') {
        occupied.remove('${row + 1}${col + 1}');
      }
    }
  }

  if (openSeats.isEmpty) return <int>[];
  List<int> result = <int>[];
  for (int s in openSeats) {
    int row = s ~/ 100;
    int col = s % 100;
    result.add(row * 100 + col);
  }
  result.sort();
  return result;
}

