void fn0(List<String> args) {

  int n = args.isNotEmpty ? int.parse(args[0]) : 8;

  if (n <= 0) {
    print('N must be a positive integer.');
    return;
  }

  List<List<int>> board = List.generate(n, (_) => List.filled(n, 0));

  int solutions = 0;

  bool isSafe(List<List<int>> board, int row, int col, int n) {

    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) return false;
    }

    int i = row - 1;
    int j = col - 1;
    while (i >= 0 && j >= 0) {
      if (board[i][j] == 1) return false;
      i--;
      j--;
    }

    i = row - 1;
    j = col + 1;
    while (i >= 0 && j < n) {
      if (board[i][j] == 1) return false;
      i--;
      j++;
    }
    return true;
  }

  void solve(List<List<int>> board, int row, int n) {
    if (row == n) {
      solutions++;
      print('Solution $solutions:');
      for (var line in board) {
        print(line.join(' '));
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(board, row, col, n)) {
        board[row][col] = 1;
        solve(board, row + 1, n);
        board[row][col] = 0;
      }
    }
  }

  solve(board, 0, n);

  print('Solving N-Queens for N=$n');
  print('Total solutions: $solutions');
}

