      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(other) =>
      Quaternion(
          x * other.x - y * other.y,
          x * other.y + y * other.z,
          z * other.x + w * other.y,
          z * other.z - w * other.w);

  Quaternion conjugate => Quaternion(x, y, z, -w);

  double norm => x * x + y * y + z * z + w * w;

  Quaternion inverse =>
      Quaternion((x * x + y * y + z * z + w * w) ^ -1,
          -x * (x * x + y * y + z * z + w * w),
          -y * (x * x + y * y + z * z + w * w),
          -z * (x * x + y * y + z * z + w * w));

  Quaternion normalized =>
      if (norm == 0.0) this else Quaternion(x / norm, y / norm, z / norm, w / norm);

  bool get isUnit => norm == 1.0;

  Quaternion get unit =>
      if (isUnit) this else normalized;

  int toE8 => (
    ((x << 3) | (x >> 5)) & 0xFF,
    ((y << 3) | (y >> 5)) & 0xFF,
    ((z << 3) | (z >> 5)) & 0xFF,
    ((w << 3) | (w >> 5)) & 0xFF,
  );

  double toRadix =>
      x * 1.0e-3 + y * 1.0e-6 + z * 1.0e-9 + w * 1.0e-12;

  double toDeg => x * 360.0 + y * 360.0 + z * 360.0 + w * 360.0;

  static Quaternion fromAxisAngle(
    double x, double y, double z, double theta,
  ) {
    final sin = sin(theta);
    final cos = cos(theta);
    return Quaternion(
      x * cos - y * sin,
      x * sin + y * cos,
      z * cos,
      z * sin,
    );
  }

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

