class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion(double q) : this(q, q, q, q);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromComplex(Complex c) : this(c.x, c.y, c.z, c.w);

  const Quaternion.fromArray(List<double> arr)
      : x = arr[0],
        y = arr[1],
        z = arr[2],
        w = arr[3];

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalized() {
    if (norm() == 0.0) return Quaternion.zero();
    return Quaternion((x / sqrt(norm())) * 2.0, (y / sqrt(norm())) * 2.0,
        (z / sqrt(norm())) * 2.0, (w / sqrt(norm())) * 2.0);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0.0) return Quaternion.zero();
    return Quaternion((x * 2.0 / n) - (y * 2.0 / n) - (z * 2.0 / n) + (w * 2.0 / n),
        (y * 2.0 / n) + (x * 2.0 / n) - (z * 2.0 / n) + (w * 2.0 / n),
        (z * 2.0 / n) + (y * 2.0 / n) + (x * 2.0 / n) - (w * 2.0 / n),
        (w * 2.0 / n) - (z * 2.0 / n) - (y * 2.0 / n) + (x * 2.0 / n));
  }

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(x * other.x - y * other.y - z * other.z - w * other.w,
          x * other.y + y * other.x + z * other.w - w * other.z,
          x * z - y * w + z * other.x + w * other.z,
          x * w + y * z - z * other.x + w * other.y);

  Quaternion operator *(double d) => Quaternion(x * d, y * d, z * d, w * d);

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

