/// Quaternion class representing a quaternion with four real number components.
class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromList(List<double> parts)
      : x = parts[0],
        y = parts[1],
        z = parts[2],
        w = parts[3];

  const Quaternion.fromArray(List<double> parts)
      : x = parts[0],
        y = parts[1],
        z = parts[2],
        w = parts[3];

  const Quaternion.fromComplex(Complex c)
      : x = c.re,
        y = c.im,
        z = -c.im,
        w = c.re;

  const Quaternion.fromUnitSphere(double magnitude, double theta) {
    final double sinTheta = sin(theta);
    final double cosTheta = cos(theta);
    x = sinTheta * cos(2 * atan2(y, z));
    y = sinTheta * sin(2 * atan2(y, z));
    z = cosTheta;
    w = cosTheta * cos(2 * atan2(y, z));
  }

  /// Calculate the norm (or magnitude) of the quaternion.
  double norm() => sqrt(x * x + y * y + z * z + w * w);

  /// Calculate the conjugate of the quaternion.
  Quaternion conjugate() => Quaternion(x, y, z, -w);

  /// Calculate the inverse of the quaternion.
  Quaternion inverse() =>
      Quaternion(x / (norm() * norm()), y / (norm() * norm()), z / (norm() * norm()), w / (norm() * norm()));

  /// Calculate the complex representation of the quaternion.
  Complex toComplex() => Complex(x + y * 1i, z + w * 1i);

  /// Calculate the rotation matrix associated with the quaternion.
  Matrix4<double> toRotationMatrix() {
    final Complex c = toComplex();
    final double r = c.abs();
    final Complex q = c / r;
    final double sinR2 = 2 * q.abs() * q.abs();
    final double cosR2 = 1 - 2 * q.abs() * q.abs();
    final double x1 = 2 * q.x * q.x - cosR2;
    final double y1 = 2 * q.y * q.y - cosR2;
    final double z1 = 2 * q.z * q.z - cosR2;
    final double xy = 2 * q.x * q.y;
    final double xz = 2 * q.x * q.z;
    final double yz = 2 * q.y * q.z;
    return Matrix4<double>(x1, xy, xz, 0,
            y1, yz, xy, 0,
            xz, yz, z1, 0,
            0, 0, 0, 1);
  }

  /// Add two quaternions.
  Quaternion operator +(Quaternion q) =>
      Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);

  /// Subtract two quaternions.
  Quaternion operator -(Quaternion q) =>
      Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);

  /// Multiply two quaternions.
  Quaternion operator *(Quaternion q) {
    final double wx = x * q.w;
    final double wy = y * q.w;
    final double wz = z * q.w;
    final double w2 = q.w * q.w;
    return Quaternion(
        x * q.x + y * wy + z * wz - w2,
        x * q.y + y * q.z + z * wy + w2,
        x * q.z + y * wz + z * q.x + w2,
        x * q.w + y * q.w + z * q.w + w2);
  }

  /// Multiply a quaternion by a scalar.
  Quaternion operator *(double s) =>
      Quaternion(x * s, y * s, z * s, w * s);

  /// Multiply a quaternion by the conjugate of another quaternion.
  Quaternion operator *=(Quaternion q) {
    x = x * q.w - y * q.z;
    y = x * q.z + y * q.w;
    z = z * q.w - w * q.x;
    w = z * q.x + w * q.w;
    return this;
  }

  @override
  String toString() =>
      'Quaternion($x, $y, $z, $w)';
}

/// A complex number class.
class Complex {
  final double re, im;

  const Complex(this.re, this.im);

  Complex operator +(Complex c) => Complex(re + c.re, im + c.im);

  Complex operator -(Complex c) => Complex(re - c.re, im - c.im);

  Complex operator *(Complex c) =>
      Complex(re * c.re - im * c.im, re * c.im + im * c.re);

  double abs() => sqrt(re * re + im * im);

  Complex conjugate() => Complex(re, -im);

  Complex inverse() =>
      Complex(re / (abs() * abs()), -im / (abs() * abs()));

  @override
  String toString() => '${re.toStringAsFixed(2)} + $im * 1i';
}

