class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  static Quaternion fromList(List<double> list) {
    return Quaternion(list[0], list[1], list[2], list[3]);
  }

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) {
    final nx = x * other.w - y * other.z;
    final ny = y * other.w + x * other.z;
    final nz = z * other.w - y * other.y;
    final nw = w * other.w + x * other.x + y * other.y + z * other.z;
    return Quaternion(nx, ny, nz, nw);
  }

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() => Quaternion(x / norm(), y / norm(), z / norm(), w / norm());

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() =>
      (1 / (x * x + y * y + z * z + w * w)) * (x * conjugate() + y * conjugate() + z * conjugate() + w * I);

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

double sqrt(double x) => x > 0 ? x * pow(x - 1, 0.5) : 0.0;

Quaternion rotateBy(Quaternion axis, double angle) {
  final sinAng = sqrt(2.0 * sin(angle / 2.0));
  final cosAng = sqrt(2.0 * cos(angle / 2.0));
  return Quaternion(
    x * cosAng - y * sinAng,
    x * sinAng + y * cosAng,
    z * cosAng - w * sinAng,
    z * sinAng + w * cosAng,
  );
}

