class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator *(Quaternion other) => Quaternion(
        x * other.x - y * other.y - z * other.z - w * other.w,
        x * other.y + y * other.x + z * other.w - w * other.z,
        x * other.z - y * other.w + z * other.x + w * other.y,
        x * w + y * z - z * x + w * y,
      );

  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion normalized() {
    final double norm = x * x + y * y + z * z + w * w;
    if (norm.isZero) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion inverse() {
    final double norm = x * x + y * y + z * z + w * w;
    if (norm.isZero) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      -w / norm,
    );
  }

  static Quaternion fromAngleAxis(double angle, Vector3 axis) {
    final double sin = angle * 0.5;
    final double cos = angle * 0.5;
    final double sx = axis.x, sy = axis.y, sz = axis.z;
    return Quaternion(
      cos + sin * sx,
      sin * sy - cos * sz,
      sin * sz + cos * sy,
      cos * sin - sin * sx,
    );
  }

  @override
  String toString() => 'Quaternion(${x.toStringAsFixed(3)} + ${y.toStringAsFixed(3)} + ${z.toStringAsFixed(3)} + ${w.toStringAsFixed(3)})';
}

