class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  /// Quaternion with zero components
  factory Quaternion() => const Quaternion(0.0, 0.0, 0.0, 0.0);

  /// Quaternion with a single real component
  factory Quaternion(double real) => const Quaternion(real, 0.0, 0.0, real);

  /// Quaternion with two real components
  factory Quaternion(double real1, double real2) => const Quaternion(real1, 0.0, 0.0, real2);

  /// Quaternion with three real components
  factory Quaternion(double real1, double real2, double real3) => const Quaternion(real1, real2, real3, 0.0);

  const Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator *(Quaternion other) => Quaternion(
        x * other.w - y * other.z - z * other.y,
        y * other.w + x * other.z,
        z * other.w + y * other.x,
        x * other.x + y * y + z * z,
      );

  const Quaternion operator /(double scalar) => Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);

  double norm() => x * x + y * y + z * z + w * w;

  const Quaternion conjugate() => const Quaternion(x, -y, -z, w);

  const Quaternion inverse() => Quaternion(
        x * x + y * y + z * z + w * w,
        -x,
        -y,
        -z,
      ) * (1 / norm());

  const Quaternion normalized() => Quaternion(
        x / norm(),
        y / norm(),
        z / norm(),
        w / norm(),
      );

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

