  int deleteCount = 0;
  int firstInsert = -1;

  while (left <= word.length) {
    if (left > word.length) {
      return 1.0;
    }

    if (right < 0) {
      return 1.0;
    }

    String c = editScript[right];
    if (c == '+') {
      if (firstInsert == -1) {
        firstInsert = left;
      }
      insertCount++;
      left++;
    } else if (c == '-') {
      deleteCount++;
      right--;
    } else if (c == '<') {
      if (left > firstInsert) {
        left = firstInsert;
      }
      deleteCount++;
      right--;
    } else if (c == '>') {
      if (right < 0) {
        return 1.0;
      }
      if (right > firstInsert) {
        right = right + (firstInsert - right);
      }
      insertCount++;
      left++;
    } else {
      return 0.0;
    }
  }

  double transitionCost = (insertCount + deleteCount) * 2.0;
  double deletionCost = deleteCount * 1.0;

  return transitionCost - deletionCost;
}

