  List<String> tokens = log.split(' ');
  List<double> deltas = [];
  for (String token in tokens) {
    if (token == 'P') {
      if (deltas.isNotEmpty) {
        deltas.removeLast();
      }
    } else if (token == 'S') {
      if (deltas.isNotEmpty) {
        deltas.add(deltas.last.abs());
      }
    } else if (token == 'M') {
      if (deltas.length >= 2) {
        double d1 = deltas.removeLast();
        double d2 = deltas.removeLast();
        deltas.add(d1 + d2);
      }
    } else if (token == 'C') {
      if (deltas.length >= 1) {
        deltas.removeLast();
      }
    } else if (token == 'D') {
      if (deltas.isNotEmpty) {
        deltas.add(0.0);
      }
    } else if (token == 'R') {
      if (deltas.isNotEmpty) {
        deltas.add(deltas.last);
      }
    } else if (token.length >= 3) {
      String zone = token.substring(0, 3);
      if (zone == 'BCA') {
        deltas.add(1.0);
      } else if (zone == 'BCD') {
        deltas.add(2.0);
      } else if (zone == 'BDC') {
        deltas.add(3.0);
      } else if (zone == 'CDB') {
        deltas.add(4.0);
      } else if (zone == 'DBC') {
        deltas.add(5.0);
      } else if (zone == 'DCB') {
        deltas.add(6.0);
      }
    }
  }
  double sum = 0.0;
  for (double d in deltas) {
    sum += d;
  }
