  final entries = <List<Object>>[];
  final numPlayers = <int>[];

  for (var i = 0; i < bracketHistory.length; i++) {
    final c = bracketHistory[i];

    if (c == 'B') {
      if (entries.isNotEmpty) {
        numPlayers.add(entries.last[1] as int);
      }
      entries.add([c, 0]);
    } else if (c == 'P') {
      if (entries.length < 2) return 0.0;
      final lastTwo = entries.removeLast();
      final prevTwo = entries.removeLast();
      final winnerIndex = (lastTwo[1] as int) < (prevTwo[1] as int)
          ? (lastTwo[1] as int) + 1
          : (prevTwo[1] as int) + 1;
      entries.add([c, winnerIndex]);
      numPlayers.add(winnerIndex);
    } else if (c == 'D') {
      if (entries.length < 2) return 0.0;
      final lastTwo = entries.removeLast();
      final prevTwo = entries.removeLast();
      entries.add([c, (lastTwo[1] as int) + (prevTwo[1] as int)]);
      numPlayers.add((lastTwo[1] as int) + (prevTwo[1] as int));
    } else if (c == 'M') {
      if (entries.length < 2) return 0.0;
      final lastTwo = entries.removeLast();
      final prevTwo = entries.removeLast();
      final winnerIndex = (lastTwo[1] as int) < (prevTwo[1] as int)
          ? (lastTwo[1] as int) + 1
          : (prevTwo[1] as int) + 1;
      entries.addAll([
        [c, winnerIndex],
        [prevTwo[0], (lastTwo[1] as int) + (prevTwo[1] as int)]
      ]);
      numPlayers.add((lastTwo[1] as int) + (prevTwo[1] as int));
    } else if (c == 'S') {
      if (numPlayers.isEmpty) return 0.0;
      final index = numPlayers.removeLast();
      entries.add([c, index]);
    } else if (c == 'C') {
      if (numPlayers.length < 2) return 0.0;
      final lastTwo = numPlayers.removeLast();
      final prevTwo = numPlayers.removeLast();
      entries.add([c, (lastTwo < prevTwo) ? lastTwo : prevTwo]);
    } else {
      return 0.0;
    }
  }

  var total = 0;
  for (final e in entries) {
    total += e[1] as int;
  }

  return total / numPlayers.length;
}

