double fn0(String input) {
  if (input.isEmpty) return 0.0;
  final List<String> tokens = input.split(' ');
  final List<double> depths = [];
  final List<double> weights = [];
  final List<int> parentIndices = [];
  int parentIndex = 0;

  for (String token in tokens) {
    if (token == '!') {
      if (parentIndices.isNotEmpty) {
        final int idx = parentIndices.removeLast();
        final double d = depths.removeLast();
        final double w = weights.removeLast();
        parentIndices[idx] = parentIndex;
        depths.add(d);
        weights.add(w);
        parentIndex++;
      }
    } else if (token == 'P') {
      if (parentIndices.isNotEmpty) {
        final int idx = parentIndices.removeLast();
        depths.add(depths[idx]);
        weights.add(weights[idx]);
        parentIndex = idx;
      }
    } else if (token == 'M') {
      if (parentIndices.isNotEmpty) {
        final int idx = parentIndices.removeLast();
        final double d = depths[idx];
        final double w = weights[idx];
        depths.add(d);
        weights.add(w);
        parentIndex = idx;
      }
    } else if (token == 'R') {
      if (parentIndices.isNotEmpty) {
        final int idx = parentIndices.removeLast();
        depths.add(depths[idx]);
        weights.add(weights[idx]);
        parentIndex = idx;
      }
    } else {
      final String kind = token[0];
      final double value = double.tryParse(token.substring(1)) ?? 0.0;
      if (kind == 'D') {
        depths.add(value);
      } else if (kind == 'W') {
        weights.add(value);
      } else if (kind == 'P') {
        parentIndices.add(parentIndex);
        parentIndex++;
      }
    }
  }

  double sum = 0.0;
  int count = 0;
  for (double d in depths) {
    if (d >= 0.0) {
      sum += d;
      count++;
    }
  }
  return count == 0 ? 0.0 : sum / count;
}

