    for (int i = 1; i < arr.length; i++) {
      if (arr[i] > mx) mx = arr[i];
    }
    return mx;
  }

  void countingSort(List<int> arr, int exp) {
    int n = arr.length;
    List<int> output = List.filled(n, 0); 
    List<int> count = List.filled(10, 0); 

    for (int i = 0; i < n; i++) {
      int digit = (arr[i] ~/ exp) % 10;
