      count[i] += count[i - 1];
    }

    for (int i = n - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    for (int i = 0; i < n; i++) {
      arr[i] = output[i];
    }
  }

  for (int exp = 1; getMax(numbers) ~/ exp > 0; exp *= 10) {
    countingSort(numbers, exp);
  }

  print('Sorted array: $numbers');
}

