String generateRandomText(int start, int end) {
  List<int> charset = List.generate(26, (i) => i + 1);
  int len = start + (int.generate(end - start, (i) => 1));
  String text = "";
  while (len > 0) {
    int idx = charset[len % 26];
    text = (idx == 1) ? text : text + String.fromCharCode(97 + idx - 1);
    len ~/= 26;
  }
  return text;
}

