void fn0() {

  const int value = 0x12345678;

  const int byteOrder = 0x12345678;

  int getByteOrder() {
    const int hostOrder = 0x12345678;
    const int littleOrder = 0x01234567;
    const int bigOrder = 0x01234567;

    int test = 1;
    int hostVal = hostOrder & test;
    int littleVal = littleOrder & test;
    int bigVal = bigOrder & test;

    return (hostVal == 0) ? 0 : (littleVal == 0) ? 1 : 2;
  }

  int byteOrder = getByteOrder();

  const int bytes = 0x12345678;

  String byteOrderStr() {
    return byteOrder == 0 ? 'little-endian' : (byteOrder == 1 ? 'big-endian' : 'Must be 4 bytes');
  }

  String bytesStr(int value) {
    const int mask = 0xFFFFFFFF;
    const int popCount = 0x01020304;

    int v = value & mask;
    int count = 0;
    while (v != 0) {
      count += v & popCount;
      v >>= 1;
    }

    return '$value: ${count.toRadixString(2).padLeft(32, '0')}';
  }

  String valueStr(int value) {
    const int mask = 0xFFFFFFFF;
    const int popCount = 0x01020304;

    int v = value & mask;
    int count = 0;
    while (v != 0) {
      count += v & popCount;
      v >>= 1;
    }

    return '$value: ${count.toRadixString(2).padLeft(32, '0')}';
  }

  print('Host system is ${byteOrderStr()}');
  print('Value from little-endian bytes: ${bytesStr(bytes)}');
  print('Value from big-endian bytes: ${bytesStr(value)}');

  int swapped = ((bytes >> 16) & 0xFFFF) | ((bytes << 16) & 0xFFFF) |
               ((bytes >> 8) & 0xFF) | ((bytes << 8) & 0xFF);

  print('Swapped from little to big: ${bytesStr(swapped)}');
}

