int fn0(List<int> bins, int k) {
  int n = bins.length;
  if (k < 0 || k >= n) return 0;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    int sum = 0;
    for (int j = 0; j < i; j++) {
      sum += bins[j];
      if (sum >= k) break;
      if (j > 0 && bins[j] == bins[j - 1]) sum -= bins[j - 1];
    }
    dp[i + 1] = sum;
  }
  return dp[n];
}

