class Role {
  String name;
  List<String> permissions;
  Role? parent;
  Map<String, Role> children = {};

  Role(this.name, [this.parent, this.permissions = const []]);

  void grantPermission(String permission) {
    if (permissions.add(permission)) {
      print('  ➜  Role "$name" now allows "$permission"');
    } else {
      print('  ➜  Permission "$permission" already exists on "$name"');
    }
  }

  void removePermission(String permission) {
    if (permissions.remove(permission)) {
      print('  ➜  Role "$name" no longer allows "$permission"');
    } else {
      print('  ➜  Permission "$permission" does not exist on "$name"');
    }
  }

  void addRole(String name, Role role) {
    children[name] = role;
  }

  void listAllRoles(String indent = '') {
    print(indent + '$name:');
    for (var perm in permissions) {
      print(indent + '  • $perm');
    }
    if (children.isNotEmpty) {
      print(indent + '➜ Children:');
      children.forEach((k, v) => v.listAllRoles('$indent  '));
    }
  }
}

class Resource {
  String name;
  Map<String, Role> accessRules = {};

  Resource(this.name);

  void grantPermission(String role, String action) {
    if (!accessRules.containsKey(role)) {
      accessRules[role] = Role();
    }
    accessRules[role]!.grantPermission('$action');
  }

  void removePermission(String role, String action) {
    if (!accessRules.containsKey(role)) {
      return;
    }
    accessRules[role]!.removePermission('$action');
  }

  void listPermissions(String role) {
    print('  • ${accessRules[role]}');
  }
}

