enum Action {

  CREATE = 0x01, 
  READ   = 0x02, 
  WRITE  = 0x04, 
  DELETE = 0x08, 

  MANAGE = 0xFF0000, 
  VIEW   = 0xFF0002, 
  EDIT   = 0xFF0004, 
  REMOVE = 0xFF0008, 
  SUCCESS = 0xFF0010, 
  DENIED  = 0xFF0018,


  INVALID = 0xFFFFFFFF
}

class Role {
  String name;
  Map<String, Action> permissions;

  Role(this.name, [this.permissions = const {}]);

  bool hasPermission(String resource, Action action) {
    if (!permissions.containsKey(resource)) {
      return false;
    }
    return permissions[resource]!.contains(action);
  }
}

class User {
