import 'dart:async';
import 'dart:convert';
enum UserRole { user, moderator, admin }

enum ResourceType {
  document1,
  document2,
  sensitiveData,
  userManagement,
  contentModeration,

  totalResources
}

class Role {
  final String name;
  final List<ResourceType> resources;

  Role(this.name, this.resources);
}

class AccessControl {
  final Map<UserRole, Set<Role>> roleHierarchy;
  final Map<UserRole, Map<ResourceType, bool>> permissions;
  final Map<String, Set<UserRole>> userRoles;
  final Map<String, UserRole?> currentUser;

  AccessControl() {

    roleHierarchy = {
      UserRole.user: {Role('user', <ResourceType>['document1', 'document2'])},
      UserRole.moderator: {Role('moderator', <ResourceType>['document1', 'document2', 'sensitiveData'])},
      UserRole.admin: {Role('admin', <ResourceType>['document1', 'document2', 'sensitiveData', 'userManagement', 'contentModeration'])},
    };

    permissions = {
      UserRole.user: {
        ResourceType.document1: true,
        ResourceType.document2: true,
      },
      UserRole.moderator: {
        ResourceType.document1: true,
        ResourceType.document2: true,
        ResourceType.sensitiveData: true,
      },
      UserRole.admin: {
        ResourceType.document1: true,
        ResourceType.document2: true,
        ResourceType.sensitiveData: true,
        ResourceType.userManagement: true,
        ResourceType.contentModeration: true,
      },
    };

    userRoles = {
      'alice': {UserRole.user},
      'bob': {UserRole.moderator},
      'charlie': {UserRole.admin},
      'diana': {UserRole.user}, 
    };

    currentUser = {};
  }

  void setCurrentUser(String username) {
    if (userRoles.containsKey(username)) {
      currentUser[username] = userRoles[username]!.first;
    } else {
      currentUser[username] = null;
    }
  }

  void grantAccess(String username, ResourceType resource) {

    setCurrentUser(username);

    if (permissions[currentUser[username]!]!.containsKey(resource)) {

      print('  ➜ User "${currentUser[username]}" attempts to access "${resource.name}"');

      if (permissions[currentUser[username]]!.remove(resource)) {
        print('  ➜ Access GRANTED (Role: ${currentUser[username]})');
      } else {
        print('  ➜ Access DENIED (Insufficient permissions)');
      }
    } else {
      print('  ➜ Resource "${resource.name}" not found');
    }
  }

  void denyAccess(String username, ResourceType resource) {

    setCurrentUser(username);

    if (permissions[currentUser[username]!]!.containsKey(resource)) {
      print('  ➜ User "${currentUser[username]}" attempts to access "${resource.name}"');
      print('  ➜ Access DENIED (Insufficient permissions)');
    } else {
      print('  ➜ Resource "${resource.name}" not found');
    }
  }

  void logAccess(String username, ResourceType resource, String action) {

    print('[$action] ${currentUser[username] == null ? 'User "' : 'User "${currentUser[username]}"'} '
        '${resource.name}: ${action == "SUCCESS" ? "GRANTED" : "DENIED"}');
  }
}

