bool userCanAccessResource({
  required String user,
  required String resource,
  required List<String> roles,
  required Map<String, List<String>> permissions,
  required Map<String, List<String>> resources,
}) {
  for (var role in roles) {
    if (permissions.containsKey(role)) {
      if (permissions[role]!.contains(resource)) {
        return true;
      }
    }
  }
  return false;
}

bool userCanAssignRole({
  required String user,
  required String role,
  required Map<String, List<String>> permissions,
  required Map<String, List<String>> roles,
}) {
  if (permissions.containsKey(role)) {
    return true;
  }
  return false;
}

