int addLE16(int a, int b) =>
    (((a & 0xFFFF) << 16) | (b & 0xFFFF)) & 0xFFFF;

int addBE32(int a, int b) =>
    (((a & 0xFFFFFFFF) | (b & 0xFFFFFFFF)) << 24) |
    (((a & 0xFFFFFFFF) >> 24) | (b & 0xFFFFFFFF)) & 0xFFFFFFFF;

int subtractLE16(int a, int b) =>
    (((a & 0xFFFF) >> 16) | (b & 0xFFFF)) & 0xFFFF;

int subtractBE32(int a, int b) =>
    (((a & 0xFFFFFFFF) - (b & 0xFFFFFFFF)) << 24) |
    (((a & 0xFFFFFFFF) >> 24) - (b & 0xFFFFFFFF)) & 0xFFFFFFFF;

int multiplyLE32(int a, int b) =>
    (((a & 0xFFFFFFFF) << 32) | (b & 0xFFFFFFFF)) & 0xFFFFFFFF;

int multiplyBE32(int a, int b) =>
    (((a & 0xFFFFFFFF) | (b & 0xFFFFFFFF)) >> 24) & 0xFFFFFFFF;

int swap16(int value) =>
    (((value >> 8) & 0xFF) << 8) | ((value & 0xFF) >> 8);

int swap32(int value) =>
    (((value >> 24) & 0xFF) << 24) |
    (((value >> 8) & 0xFF) << 8) |
    (((value & 0xFF) >> 8) << 16) |
    (((value & 0xFF) & 0xFF) >> 16));

