void fn0() {

  int value = 0x12345678;

  int bigEndianValue = value.toBigInt();

  int littleEndianValue = bigEndianValue.toLittleInt();

  print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('As Little Endian bytes: [${littleEndianValue.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('As Big Endian bytes:   [${bigEndianValue.toRadixString(16).toUpperCase().padLeft(8, '0')}]');

  int swap16(int value) {
    int bytes = value & 0xFFFF;
    bytes = ((bytes << 8) & 0xFFFF) | ((bytes >> 8) & 0xFFFF);
    return bytes;
  }

  int swap32(int value) {
    int bytes = value & 0xFFFFFFFF;
    bytes = ((bytes << 24) & 0xFFFFFFFF) |
           ((bytes >> 24) & 0xFFFFFFFF) |
           ((bytes >> 16) & 0xFFFF) |
           ((bytes >> 8) & 0xFFFF);
    return bytes;
  }

  int swaped = swap16(value);
  int swaped32 = swap32(value);

  print('16-bit swap of 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('Swap back: 0x${swaped.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('32-bit swap of 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('Swap back: 0x${swaped32.toRadixString(16).toUpperCase().padLeft(8, '0')}');

  int networkByteOrderValue = 0xABCD;

  int beBytes = networkByteOrderValue.toBigInt();
  int leBytes = beBytes.toLittleInt();

  print('Network byte order example:');
  print('0x${networkByteOrderValue.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('As Little Endian bytes: [${leBytes.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('As Big Endian bytes:   [${beBytes.toRadixString(16).toUpperCase().padLeft(8, '0')}]');

  double floatValue = 3.14159;
  int floatBe = floatValue.toBigInt();
  int floatLe = floatBe.toLittleInt();

  print('Float Endianness Example:');
  print('Float value: $floatValue');
  print('As Little Endian bytes: [${floatLe.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('As Big Endian bytes:   [${floatBe.toRadixString(16).toUpperCase().padLeft(8, '0')}]');

  SystemInformation sysInfo = SystemInformation.current;

  print('System Information:');
  print('Endianness: ${sysInfo.endian == Endian.little ? 'Little Endian' : 'Big Endian'}');
  print('Host port: ${sysInfo.hostPort}');

  int hostPort = 0x5678;
  int swappedHost = sysInfo.endian == Endian.little ? hostPort.toLittleInt() : hostPort.toBigInt();

  print('Back to host: ${swappedHost.toRadixString(16).toUpperCase().padLeft(4, '0')}');


  int arrayLE = [1, 2, 3, 4].map((v) => v & 0xFFFFFFFF).join(',').toLittleInt();
  int arrayBE = [1, 2, 3, 4].map((v) => v & 0xFFFFFFFF).join(',').toBigInt();

  print('Array Endianness Conversion:');
  print('Little Endian bytes: [${arrayLE.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('Big Endian bytes:   [${arrayBE.toRadixString(16).toUpperCase().padLeft(8, '0')}]');

  List<int> little = [0x12345678, 0x90ABCDEF];
  List<int> big = [0xABCD, 0x12345678];

  print('Endianness Swapping:');
  print('Original 16-bit values: [${little[0].toRadixString(16).toUpperCase().padLeft(4, '0'), '${little[1].toRadixString(16).toUpperCase().padLeft(4, '0')}]');
  print('Swapped values:        [${big[0].toRadixString(16).toUpperCase().padLeft(4, '0'), '${big[1].toRadixString(16).toUpperCase().padLeft(4, '0')}]');

  List<int> bytesLE = little.map((v) => v & 0xFFFFFFFF).join(',').toLittleInt();
  List<int> bytesBE = big.map((v) => v & 0xFFFFFFFF).join(',').toBigInt();

  print('Byte stream (BE):   [${bytesBE.toRadixString(16).toUpperCase().padLeft(8, '0')}]');
  print('Byte stream (LE):   [${bytesLE.toRadixString(16).toUpperCase().padLeft(8, '0')}]');


  int le32 = 0x1234567890ABCDEF;
  int be32 = le32.toBigInt();

  print('Little Endian Operations:');
  print('0x${le32.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  print('To bytes:  [${be32.toRadixString(16).toUpperCase().padLeft(8, '0')}]');

