class SystemInformation {
  final Endian endian;
  final int hostPort;

  SystemInformation._internal(this.endian, this.hostPort);

  factory SystemInformation.current() =>
      _internal(
        Endian.of(Platform.isLittleEndian ? 1 : 2),
        Platform.hostPort,
      );
}

