Map<String, int> fn0(List<int> dailyPackets, int targetInterval) {
  if (dailyPackets.isEmpty) {
    return {'longestInterval': 0, 'totalDeficitDays': 0, 'distinctIntervals': 0};
  }

  int currentInterval = 0;
  List<int> intervals = [];

  for (int i = 0; i < dailyPackets.length; i++) {
    int interval = i == 0 ? 1 : dailyPackets[i] - dailyPackets[i - 1];
    currentInterval = interval;

    if (interval >= targetInterval) {
      intervals.add(interval);
      if (currentInterval > intervals.last) {
        intervals.removeLast();
      }
    } else if (currentInterval < targetInterval) {
      for (int j = intervals.length - 1; j >= 0; j--) {
        if (intervals[j] >= targetInterval) {
          intervals.removeAt(j);
          break;
        }
      }
    }
  }

  int longestInterval = 0;
  int totalDeficitDays = 0;
  int distinctIntervals = 0;

  for (int interval in intervals) {
    if (interval > longestInterval) {
      longestInterval = interval;
    }
    totalDeficitDays += targetInterval - interval;
    distinctIntervals++;
  }

  return {'longestInterval': longestInterval, 'totalDeficitDays': totalDeficitDays, 'distinctIntervals': distinctIntervals};
}

