        pointsInCluster.map((p) => p[0]).reduce((a, b) => a + b) / pointsInCluster.length,
        pointsInCluster.map((p) => p[1]).reduce((a, b) => a + b) / pointsInCluster.length,
      ];
    }

    final newAssignments = <int>[];
    for (int i = 0; i < numPoints; i++) {
      newAssignments.add(assignments[i]);
