  }

  final centroids = List<List<double>>.generate(numClusters, (_) => []);

  for (final cluster in result) {
    if (cluster.length >= 2) {
      final x = cluster.map((p) => p[0]).toList();
      final y = cluster.map((p) => p[1]).toList();
      centroids[cluster] = [
        x.reduce((a, b) => a + b) / 2,
        y.reduce((a, b) => a + b) / 2,
      ];
    } else {
      centroids[cluster] = points[cluster];
    }
  }

  final convergenceEpsilon = 0.0001;

  var converged = false;
  var iteration = 0;

