      (left[1] + right[1]) / 2.0,
    ];
  }

  List<int> assignments =
      List<int>.filled(points.length, -1);

  double distanceToCentroids(List<double> point) {
    double minDist = double.infinity;
    for (final c in clusterCentroids(points)) {
      final dist = euclideanDistance(point, c);
      if (dist < minDist) minDist = dist;
    }
    return minDist;
  }

  int assign(List<double> point) {
    return assignments.isEmpty
        ? -1
        : assignments[0] == -1
            ? assignCluster(point)
            : assignCluster(point);
  }

  int assignCluster(List<double> point) {
    double minDist = double.infinity;
    int bestCluster = -1;
    for (int i = 0; i < points.length; i++) {
      final dist = euclideanDistance(point, points[i]);
      if (dist < minDist) {
        minDist = dist;
        bestCluster = i;
      }
    }
    return bestCluster;
  }

  for (int iter = 0; iter < 100; iter++) {
    bool changed = false;
    for (int i = 0; i < points.length; i++) {
      final currentCluster = assignments[i];
      if (currentCluster != -1) {
        final newCluster = assign(points[i]);
        if (newCluster != currentCluster) {
          assignments[i] = newCluster;
          changed = true;
        }
      }
    }
    if (!changed) {
      break;
    }

    if (iter % 10 == 0) {
      print('Cluster ${iter + 1}:');
      for (int i = 0; i < points.length; i++) {
        final cluster = assignments[i];
        print('  Points: ${points[i]}');
      }
      print('centroid: ${clusterCentroids(points)}');
    }
  }

  print('Converged in $iter iteration(s).');
}

