  bool pointInCluster(int idx, List<List<int>> labels, List<List<double>> centroids) {
    for (int i = 0; i < labels.length; i++) {
      if (labels[i] == idx) return true;
    }
    for (int i = 0; i < centroids.length; i++) {
      double dist = 0.0;
      for (int j = 0; j < points[idx].length; j++) {
        double diff = points[idx][j] - centroids[i][j];
        dist += diff * diff;
      }
      if (dist <= eps * eps && !labels.contains(i)) {
        labels.add(i);
        return true;
      }
    }
    return false;
  }

